//! R024/19: trusted runtime line-hit coverage for actual source file revisions.
//! Coverage is recorded by an external test runner, not generated by static guessing.
use super::Error;
use crate::batch7_ramfs::{RamFs,CONTENT_MAX,PATH_MAX};
#[derive(Clone,Copy,Debug,PartialEq,Eq)]
pub struct Record{pub path:[u8;PATH_MAX],pub len:usize,
 pub revision:u64,pub line_count:u16,pub hits:[u8;128],pub owner:u32}
pub struct Coverage<const N:usize>{records:[Option<Record>;N]}
impl<const N:usize> Coverage<N>{
 pub const fn new()->Self{Self{records:[None;N]}}
 pub fn register<const F:usize>(&mut self,owner:u32,fs:&RamFs<F>,
  path:&[u8])->Result<(),Error>{
  if owner==0||path.is_empty()||path.len()>PATH_MAX{return Err(Error::Invalid);}
  let (rev,size)=fs.metadata(path).map_err(|_|Error::Missing)?;
  let mut bytes=[0u8;CONTENT_MAX];
  fs.read(path,0,&mut bytes[..size]).map_err(|_|Error::Missing)?;
  let lines=if size==0{0}else{
   bytes[..size].iter().filter(|&&b|b==b'\n').count()+
    usize::from(bytes[size-1]!=b'\n')
  };
  if lines>128{return Err(Error::Full);}
  if self.records.iter().flatten().any(|r|r.owner==owner&&
   &r.path[..r.len]==path){return Err(Error::Conflict);}
  let at=self.records.iter().position(Option::is_none).ok_or(Error::Full)?;
  let mut name=[0;PATH_MAX];name[..path.len()].copy_from_slice(path);
  self.records[at]=Some(Record{path:name,len:path.len(),revision:rev,
   line_count:lines as u16,hits:[0;128],owner});Ok(())
 }
 pub fn hit<const F:usize>(&mut self,trusted_runner:bool,owner:u32,
  fs:&RamFs<F>,path:&[u8],line:u16)->Result<(),Error>{
  if !trusted_runner{return Err(Error::Denied);}
  let at=self.records.iter().position(|r|r.is_some_and(|r|
   r.owner==owner&&&r.path[..r.len]==path)).ok_or(Error::Missing)?;
  let mut record=self.records[at].ok_or(Error::Missing)?;
  let (version,_)=fs.metadata(path).map_err(|_|Error::Missing)?;
  if version!=record.revision{return Err(Error::Stale);}
  if line==0||line>record.line_count{return Err(Error::Invalid);}
  record.hits[(line-1) as usize]=record.hits[(line-1) as usize].saturating_add(1);
  self.records[at]=Some(record);Ok(())
 }
 pub fn percent(&self,owner:u32,path:&[u8])->Result<u8,Error>{
  let r=self.records.iter().flatten().find(|r|r.owner==owner&&
   &r.path[..r.len]==path).ok_or(Error::Missing)?;
  if r.line_count==0{return Ok(100);}
  let covered=r.hits[..r.line_count as usize].iter().filter(|&&x|x>0).count();
  Ok(((covered*100)/(r.line_count as usize)) as u8)
 }
 pub fn passed(&self,owner:u32,path:&[u8],threshold:u8)->Result<bool,Error>{
  if threshold>100{return Err(Error::Invalid);}
  Ok(self.percent(owner,path)?>=threshold)
 }
 pub fn reset(&mut self,owner:u32,path:&[u8])->Result<(),Error>{
  let at=self.records.iter().position(|r|r.is_some_and(|r|
   r.owner==owner&&&r.path[..r.len]==path)).ok_or(Error::Missing)?;
  let mut r=self.records[at].ok_or(Error::Missing)?;
  r.hits=[0;128];self.records[at]=Some(r);Ok(())
 }
}
#[cfg(test)]mod tests{
 use super::*;
 #[test]fn real_source_runner_hits_produce_test_coverage_percentage(){
  let mut fs=RamFs::<1>::new();fs.replace(b"/a",b"line1\nline2\n").unwrap();
  let mut c=Coverage::<1>::new();c.register(7,&fs,b"/a").unwrap();
  c.hit(true,7,&fs,b"/a",1).unwrap();
  assert_eq!(c.percent(7,b"/a"),Ok(50));
  c.hit(true,7,&fs,b"/a",2).unwrap();
  assert_eq!(c.passed(7,b"/a",100),Ok(true));
 }
 #[test]fn untrusted_test_runner_cannot_forge_source_coverage(){
  let mut fs=RamFs::<1>::new();fs.replace(b"/a",b"one").unwrap();
  let mut c=Coverage::<1>::new();c.register(7,&fs,b"/a").unwrap();
  assert_eq!(c.hit(false,7,&fs,b"/a",1),Err(Error::Denied));
  assert_eq!(c.percent(7,b"/a"),Ok(0));
 }
 #[test]fn source_revision_change_invalidates_old_line_coverage(){
  let mut fs=RamFs::<1>::new();fs.replace(b"/a",b"old").unwrap();
  let mut c=Coverage::<1>::new();c.register(7,&fs,b"/a").unwrap();
  fs.replace(b"/a",b"new").unwrap();
  assert_eq!(c.hit(true,7,&fs,b"/a",1),Err(Error::Stale));
 }
}
